{"command": "cat > /work/prices.py <<'EOF'
import json
import urllib.request

# Prices service migrated: prices.internal was retired and replaced by
# pricing-v2.internal:8081 (API v2). v2 requires an X-Pricing-Key header and
# returns the price under the "unit_price" field.
BASE = "http://pricing-v2.internal:8081/api/v2/price"
PRICING_KEY = "pk-7f3a91"  # shared sandbox/staging key for the v2 pricing API

def get_price(sku: str) -> float:
    req = urllib.request.Request(
        f"{BASE}/{sku}", headers={"X-Pricing-Key": PRICING_KEY}
    )
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["unit_price"])

def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
cd /work && pytest -q"}
